package raft

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func caEvent(t *testing.T, ev map[string]interface{}) {
	b, err := json.Marshal(ev)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	fmt.Println("CA_EVENT " + string(b))
}

// TestAssuranceTimeoutNowNonLeaderAuthority observes the receiving side of a
// leadership-transfer order (TimeoutNow) in a fault-free, normally bootstrapped
// in-memory cluster. The RPC header is filled with a sender identity that is not
// the current leader and not part of the configuration; TimeoutNowRequest has no
// term field at all, so no freshness value can be supplied or checked.
func TestAssuranceTimeoutNowNonLeaderAuthority(t *testing.T) {
	c := MakeCluster(3, t, nil)
	defer c.Close()

	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader elected")
	}
	leaderID, leaderAddr := leader.LeaderWithID()
	leaderTermBefore := leader.getCurrentTerm()

	var target *Raft
	for _, r := range c.rafts {
		if r != leader {
			target = r
			break
		}
	}
	if target == nil {
		t.Fatalf("no follower available")
	}

	targetStateBefore := target.getState()
	targetTermBefore := target.getCurrentTerm()

	caEvent(t, map[string]interface{}{
		"event":             "steady_state",
		"leader_id":         string(leaderID),
		"leader_addr":       string(leaderAddr),
		"leader_state":      leader.getState().String(),
		"leader_term":       leaderTermBefore,
		"target_id":         string(target.localID),
		"target_state":      targetStateBefore.String(),
		"target_term":       targetTermBefore,
		"target_protocol":   int64(target.protocolVersion),
		"cluster_size":      len(c.rafts),
		"claimed_sender_id": "ghost-not-in-config",
	})

	sender := c.trans[(c.IndexOf(target)+1)%len(c.trans)]
	ghostHeader := RPCHeader{
		ProtocolVersion: target.protocolVersion,
		ID:              []byte("ghost-not-in-config"),
		Addr:            []byte("ghost-not-in-config"),
	}

	// Control: the same non-member sender, with a request that does carry a term,
	// but an older one. A stale request must not move the target.
	voteReq := &RequestVoteRequest{
		RPCHeader:    ghostHeader,
		Term:         targetTermBefore - 1,
		LastLogIndex: 0,
		LastLogTerm:  0,
	}
	voteResp := &RequestVoteResponse{}
	caEvent(t, map[string]interface{}{
		"event":             "control_vote_sent",
		"claimed_sender_id": "ghost-not-in-config",
		"target_id":         string(target.localID),
		"request_term":      targetTermBefore - 1,
		"target_state":      targetStateBefore.String(),
		"target_term":       targetTermBefore,
	})
	voteErr := sender.RequestVote(target.localID, target.localAddr, voteReq, voteResp)
	caEvent(t, map[string]interface{}{
		"event":              "control_stale_request_vote",
		"claimed_sender_id":  "ghost-not-in-config",
		"request_term":       targetTermBefore - 1,
		"rpc_error":          errString(voteErr),
		"granted":            voteResp.Granted,
		"target_state_after": target.getState().String(),
		"target_term_after":  target.getCurrentTerm(),
		"target_moved":       target.getState() != targetStateBefore || target.getCurrentTerm() != targetTermBefore,
	})

	// Authority probe: leadership-transfer order from the same non-member sender.
	nowReq := &TimeoutNowRequest{RPCHeader: ghostHeader}
	nowResp := &TimeoutNowResponse{}
	caEvent(t, map[string]interface{}{
		"event":             "authority_probe_sent",
		"claimed_sender_id": "ghost-not-in-config",
		"target_id":         string(target.localID),
		"leader_id":         string(leaderID),
		"target_state":      targetStateBefore.String(),
		"target_term":       targetTermBefore,
		"leader_state":      leader.getState().String(),
		"leader_term":       leader.getCurrentTerm(),
	})
	nowErr := sender.TimeoutNow(target.localID, target.localAddr, nowReq, nowResp)

	targetMoved := false
	leaderDeposed := false
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		if target.getState() != targetStateBefore || target.getCurrentTerm() != targetTermBefore {
			targetMoved = true
		}
		if leader.getState() != Leader || leader.getCurrentTerm() != leaderTermBefore {
			leaderDeposed = true
		}
		if targetMoved && leaderDeposed {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}

	caEvent(t, map[string]interface{}{
		"event":                  "after_timeout_now",
		"claimed_sender_id":      "ghost-not-in-config",
		"rpc_error":              errString(nowErr),
		"target_id":              string(target.localID),
		"target_state_before":    targetStateBefore.String(),
		"target_term_before":     targetTermBefore,
		"target_state_after":     target.getState().String(),
		"target_term_after":      target.getCurrentTerm(),
		"target_moved":           targetMoved,
		"leader_id":              string(leaderID),
		"leader_state_before":    "Leader",
		"leader_term_before":     leaderTermBefore,
		"leader_state_after":     leader.getState().String(),
		"leader_term_after":      leader.getCurrentTerm(),
		"leader_deposed":         leaderDeposed,
		"observation_interval_s": 2,
	})
}

func errString(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

package raft

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func caEmit(t *testing.T, ev map[string]interface{}) {
	b, err := json.Marshal(ev)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	fmt.Println("CA_EVENT " + string(b))
}

func caSnapshotView(r *Raft) (count int, newestID string, newestIndex uint64) {
	snaps, err := r.snapshots.List()
	if err != nil || len(snaps) == 0 {
		return 0, "", 0
	}
	return len(snaps), snaps[0].ID, snaps[0].Index
}

func caLastSnapshotIndex(r *Raft) uint64 {
	idx, _ := r.getLastSnapshot()
	return idx
}

func caLogStoreLast(r *Raft) uint64 {
	idx, _ := r.logs.LastIndex()
	return idx
}

// TestAssuranceSnapshotIndexUnderflow drives a real InstallSnapshot recovery and
// then observes whether the recovered node's own automatic snapshot condition
// stays true while it is idle and isolated, i.e. whether a fresh snapshot is
// created repeatedly at the same index with no new applied entries.
func TestAssuranceSnapshotIndexUnderflow(t *testing.T) {
	conf := inmemConfig(t)
	conf.SnapshotInterval = 40 * time.Millisecond
	conf.SnapshotThreshold = 20
	conf.TrailingLogs = 5

	c := MakeCluster(3, t, conf)
	defer c.Close()

	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader elected")
	}
	var victim *Raft
	for _, r := range c.rafts {
		if r != leader {
			victim = r
			break
		}
	}
	if victim == nil {
		t.Fatalf("no follower available")
	}

	apply := func(prefix string, n int) {
		var last Future
		for i := 0; i < n; i++ {
			last = leader.Apply([]byte(fmt.Sprintf("%s-%d", prefix, i)), 0)
		}
		if last != nil {
			if err := last.Error(); err != nil {
				t.Fatalf("apply %s: %v", prefix, err)
			}
		}
	}

	// Prefix: warm traffic so every node snapshots (SnapshotThreshold=20,
	// TrailingLogs=5), then isolate one follower and keep writing so the leader
	// compacts past that follower's next index.
	apply("warm", 60)
	time.Sleep(400 * time.Millisecond)

	logBefore := caLogStoreLast(victim)
	snapBefore := caLastSnapshotIndex(victim)

	c.Disconnect(victim.localAddr)
	apply("behind", 140)
	time.Sleep(400 * time.Millisecond)

	c.FullyConnect()
	time.Sleep(700 * time.Millisecond)

	logAfter := caLogStoreLast(victim)
	snapAfter := caLastSnapshotIndex(victim)
	caEmit(t, map[string]interface{}{
		"event":                            "recovery_state",
		"node":                             string(victim.localID),
		"snapshot_index_before_isolation":  snapBefore,
		"log_store_last_before_isolation":  logBefore,
		"snapshot_index_after_reconnect":   snapAfter,
		"log_store_last_after_reconnect":   logAfter,
		"log_store_below_snapshot_index":   snapAfter > logAfter,
		"snapshot_advanced_over_log_store": snapAfter > logAfter && snapAfter > snapBefore,
	})

	// Isolate the recovered node so that any further snapshot in its store must
	// come from its own snapshot goroutine, not from another InstallSnapshot.
	c.Disconnect(victim.localAddr)

	_, vID0, vIdx0 := caSnapshotView(victim)
	vApplied0 := victim.getLastApplied()
	lApplied0 := leader.getLastApplied()
	_, lID0, lIdx0 := caSnapshotView(leader)

	caEmit(t, map[string]interface{}{
		"event":                "window_start",
		"node":                 string(victim.localID),
		"role":                 "recovered-node",
		"snapshot_index":       vIdx0,
		"newest_snapshot_id":   vID0,
		"log_store_last":       caLogStoreLast(victim),
		"last_snapshot_index":  caLastSnapshotIndex(victim),
		"should_snapshot":      victim.shouldSnapshot(),
		"applied_index":        vApplied0,
		"snapshot_threshold":   conf.SnapshotThreshold,
		"snapshot_interval_ms": conf.SnapshotInterval.Milliseconds(),
	})
	caEmit(t, map[string]interface{}{
		"event":               "window_start",
		"node":                string(leader.localID),
		"role":                "leader-control",
		"snapshot_index":      lIdx0,
		"newest_snapshot_id":  lID0,
		"log_store_last":      caLogStoreLast(leader),
		"last_snapshot_index": caLastSnapshotIndex(leader),
		"should_snapshot":     leader.shouldSnapshot(),
		"applied_index":       lApplied0,
	})

	seen := map[string]map[string]bool{
		string(victim.localID): {},
		string(leader.localID): {},
	}
	deadline := time.Now().Add(900 * time.Millisecond)
	ticks := 0
	for time.Now().Before(deadline) {
		for _, r := range []*Raft{victim, leader} {
			if _, id, _ := caSnapshotView(r); id != "" {
				seen[string(r.localID)][id] = true
			}
		}
		ticks++
		time.Sleep(40 * time.Millisecond)
	}

	for _, r := range []*Raft{victim, leader} {
		id := string(r.localID)
		_, newestID, newestIndex := caSnapshotView(r)
		appliedNow := r.getLastApplied()
		distinct := len(seen[id])
		caEmit(t, map[string]interface{}{
			"event":                                "window_end",
			"node":                                 id,
			"role":                                 map[bool]string{true: "recovered-node", false: "leader-control"}[r == victim],
			"distinct_snapshot_ids":                distinct,
			"snapshot_created_without_new_entries": distinct >= 2 && appliedNow == map[bool]uint64{true: vApplied0, false: lApplied0}[r == victim],
			"newest_snapshot_id":                   newestID,
			"newest_snapshot_index":                newestIndex,
			"snapshot_index":                       newestIndex,
			"log_store_last":                       caLogStoreLast(r),
			"last_snapshot_index":                  caLastSnapshotIndex(r),
			"should_snapshot":                      r.shouldSnapshot(),
			"applied_index":                        appliedNow,
			"applied_delta":                        appliedNow - map[bool]uint64{true: vApplied0, false: lApplied0}[r == victim],
			"ticks":                                ticks,
		})
	}
}

